pbx += `\t};\n\trootObject = ${PROJ} /* Project object */;\n}\n`;

const projDir = path.join(IOS, 'LegadoMobile.xcodeproj');
fs.mkdirSync(projDir, { recursive: true });
fs.writeFileSync(path.join(projDir, 'project.pbxproj'), pbx, 'utf8');

// shared scheme so `xcodebuild -scheme LegadoMobile` works in CI
const schemeDir = path.join(projDir, 'xcshareddata', 'xcschemes');
